def seed_phase_3(apps, schema_editor):
    Permission = apps.get_model("users", "Permission")
    Role = apps.get_model("users", "Role")
    RolePermission = apps.get_model("users", "RolePermission")
    Website = apps.get_model("websites", "Website")
    WebsitePage = apps.get_model("websites", "WebsitePage")
    WebsiteMenu = apps.get_model("websites", "WebsiteMenu")
    WebsiteMenuItem = apps.get_model("websites", "WebsiteMenuItem")
    permission, _ = Permission.objects.update_or_create(
        code="manage.website.media",
        defaults={"action_name": "manage", "module": "website.media", "description": "Gestionar medios del sitio web"},
    )
    for role in Role.objects.filter(models.Q(name__iexact="ADMIN") | models.Q(name__iexact="SUPERUSER")):
        RolePermission.objects.get_or_create(role=role, permission=permission)
    for website in Website.objects.all().iterator():
        header, _ = WebsiteMenu.objects.get_or_create(website=website, location="HEADER", defaults={"name": "Navegación principal"})
        WebsiteMenu.objects.get_or_create(website=website, location="FOOTER", defaults={"name": "Pie de página"})
        home = WebsitePage.objects.filter(website=website, page_type="HOME").first()
        if home:
            WebsiteMenuItem.objects.get_or_create(
                menu=header, parent=None, position=0,
                defaults={"label": "Inicio", "target_type": "PAGE", "page": home},
            )


def unseed_phase_3(apps, schema_editor):
    apps.get_model("users", "Permission").objects.filter(code="manage.website.media").delete()


